import json,pathlib
p=pathlib.Path(__file__).parent
for lang in ('en','da'):
 src='source-anna-karenina'+('.da' if lang=='da' else '')+'.json';d=json.loads((p/src).read_text());before=json.loads((p/src).read_text())
 if lang=='en':
  d.update(era='1875–1877; first complete book edition 1878',about='Anna Karenina follows intertwined stories of love, family and the search for a meaningful life. Anna comes to Moscow to help her brother Stiva and his wife Dolly after his infidelity. There she meets Count Vronsky. Meanwhile, the landowner Konstantin Levin hopes to marry Dolly’s younger sister Kitty. The novel moves between these households, city society and country work, allowing different characters to experience the same events very differently.\n\nTolstoy worked on the novel from 1873 to 1877. The first seven parts appeared in The Russian Messenger in 1875–1877. A disagreement with its editor over the final part’s treatment of Russian volunteers supporting Serbia led to Part Eight appearing separately in 1877. The first complete book edition followed in 1878.\n\nRead the social scenes as closely as the dramatic ones: a glance, an invitation, a missed visit or a change of address can alter a relationship. Levin’s questions about work, faith and responsibility belong to the same novel as Anna’s story. Neither strand can be reduced to a simple lesson about who deserves happiness.')
  cards=[('Anna and her society','Follow how Anna’s relationships change as private feelings become public knowledge. Notice the different freedoms granted to men and women.','I want to follow Anna’s choices, attachments and isolation, while distinguishing other characters’ judgments from the narrator’s.'),('Levin’s questions','Levin seeks a meaningful way to live through farming, family, reading and faith. Watch how practical life complicates his theories.','I want to track what Levin learns from work, love and other people, and what his final insight does and does not resolve.'),('Three households','Compare the Oblonskys, the Karenins and the family Levin and Kitty build. Money, children, work and social expectations shape each household.','I want to compare the three families without assuming that one supplies a simple model for the others.'),('Names and voices','A person may appear under a first name, patronymic, surname or affectionate nickname. Stiva is Stepan; Dolly is Darya; Kitty is Ekaterina; Kostya is Konstantin; Seryozha is Sergey.','I want to follow changing forms of address and notice whose perceptions shape each scene.')]
  casts=[('Anna Arkadyevna Karenina','Anna','Stiva’s sister, Karenin’s wife and Seryozha’s mother. Her visit to Moscow brings her into Vronsky’s orbit. Her intelligence and social confidence coexist with needs and fears that others often fail to understand.'),('Count Alexey Kirillovich Vronsky','Vronsky','A wealthy cavalry officer who attracts Kitty’s hopes before falling in love with Anna. His ambitions, friendships and sense of honor do not always fit the life Anna needs.'),('Alexey Alexandrovitch Karenin','Karenin','Anna’s older husband, a senior government official. His concern for duty, reputation and religious obligation intersects with genuine suffering and moments of compassion.'),('Konstantin Dmitrievitch Levin','Levin','A landowner concerned with farming, family and the purpose of life. His brothers Nikolay and Sergey Ivanovitch reveal different possibilities for living and thinking.'),('Princess Ekaterina “Kitty” Shtcherbatskaya','Kitty','Dolly’s younger sister. Her disappointment, recovery and growing confidence form a story of their own. Her practical care repeatedly challenges Levin’s assumptions.'),('Prince Stepan “Stiva” Arkadyevitch Oblonsky','Stiva','Anna’s brother and Dolly’s husband. Charming and sociable, he often leaves others to bear the cost of his appetites and financial choices.'),('Darya “Dolly” Alexandrovna Oblonskaya','Dolly','Stiva’s wife and Kitty’s elder sister. Childcare, money and her husband’s infidelity shape her daily life. Her visits and conversations connect the novel’s households.')]
  why=[('A question about families','The opening claim about happy and unhappy families invites testing against the lives that follow. Love does not remove the pressure of money, children, habits or unequal expectations. Notice how a household looks different from inside each person’s experience.'),('A changing society','The novel places intimate decisions alongside farming, provincial elections, government jobs and debate about war. The final discussions concern volunteers supporting Serbia against the Ottoman Empire. Speakers disagree about compassion, nationalism, public opinion and the right to make war; their arguments are not interchangeable with an editorial verdict.'),('Meaning in ordinary life','Levin’s reflections grow from experiences that thinking alone cannot settle: illness, marriage, childbirth, work and fear for those he loves. His concluding insight does not make him instantly patient or free of doubt. Read the ordinary conversation around it alongside the reflection itself.')]
 else:
  d.update(author='Lev Tolstoj',era='1875–1877; første samlede bogudgave 1878',openingChapterLabel='Del I, kapitel 1 — Familien Oblonskij',about='Anna Karenina fletter fortællinger om kærlighed, familie og meningen med livet sammen. Anna kommer til Moskva for at hjælpe sin bror Stiva og hans kone Dolly efter hans utroskab. Her møder hun grev Vronskij. Samtidig håber godsejeren Konstantin Levin at blive gift med Dollys yngre søster Kitty. Romanen bevæger sig mellem familierne, byens selskabsliv og arbejdet på landet og viser, hvor forskelligt personerne kan opleve den samme begivenhed.\n\nTolstoj arbejdede på romanen fra 1873 til 1877. De første syv dele udkom som føljeton i tidsskriftet Den russiske budbringer i 1875–1877. En uenighed med redaktøren om sidste dels skildring af russiske frivillige, der støttede Serbien, førte til, at ottende del udkom særskilt i 1877. Den første samlede bogudgave fulgte i 1878.\n\nLæs selskabsscenerne lige så opmærksomt som de dramatiske optrin: et blik, en invitation, et udeblevet besøg eller en ændret tiltaleform kan forskyde et forhold. Levins spørgsmål om arbejde, tro og ansvar hører til samme roman som Annas historie. Ingen af de to fortællinger lader sig reducere til en enkel lære om, hvem der fortjener lykken.')
  cards=[('Anna og hendes omgivelser','Følg, hvordan Annas forhold til andre ændrer sig, når private følelser bliver offentligt kendte. Læg mærke til mændenes og kvindernes forskellige muligheder.','Jeg vil følge Annas valg, kærlighed og isolation og skelne mellem de andre personers domme og fortællerens fremstilling.'),('Levins spørgsmål','Levin søger en meningsfuld måde at leve på gennem landbrug, familieliv, læsning og tro. Se, hvordan hverdagen udfordrer hans teorier.','Jeg vil følge, hvad Levin lærer af arbejde, kærlighed og andre mennesker, og hvad hans sidste erkendelse løser og ikke løser.'),('Tre familier','Sammenlign familien Oblonskij, familien Karenin og det hjem, Levin og Kitty bygger op. Penge, børn, arbejde og sociale forventninger præger dem alle.','Jeg vil sammenligne familierne uden på forhånd at gøre én af dem til forbillede for de andre.'),('Navne og stemmer','Den samme person kan omtales med fornavn, fadernavn, efternavn eller kælenavn. Stiva er Stepan, Dolly er Darja, Kitty er Jekaterina, Kostja er Konstantin, og Serjozja er Sergej.','Jeg vil lægge mærke til tiltaleformerne og til, hvis oplevelse af verden der præger den enkelte scene.')]
  casts=[('Anna Arkadjevna Karenina','Anna','Stivas søster, Karenins kone og Serjozjas mor. Under sit besøg i Moskva møder hun Vronskij. Hendes intelligens og sociale sikkerhed ledsages af behov og frygt, som andre ofte ikke forstår.'),('Grev Aleksej Kirillovitj Vronskij','Vronskij','En velhavende kavalleriofficer, som Kitty håber at blive gift med, før han forelsker sig i Anna. Hans ambitioner, venskaber og æresbegreber passer ikke altid til det liv, Anna har brug for.'),('Aleksej Aleksandrovitj Karenin','Karenin','Annas ældre mand, en højtstående embedsmand. Hans hensyn til pligt, anseelse og religiøse forpligtelser møder både ægte lidelse og øjeblikke af medfølelse.'),('Konstantin Dmitrijevitj Levin','Levin','En godsejer, der er optaget af landbrug, familie og livets mening. Hans brødre Nikolaj og Sergej Ivanovitj viser andre muligheder for at leve og tænke.'),('Fyrstinde Jekaterina »Kitty« Sjtjerbatskaja','Kitty','Dollys yngre søster. Hendes skuffelse, bedring og voksende selvtillid udgør en selvstændig fortælling. Hendes praktiske omsorg udfordrer gang på gang Levins forestillinger.'),('Fyrst Stepan »Stiva« Arkadjevitj Oblonskij','Stiva','Annas bror og Dollys mand. Han er charmerende og selskabelig, men lader ofte andre betale prisen for sine lyster og økonomiske valg.'),('Darja »Dolly« Aleksandrovna Oblonskaja','Dolly','Stivas kone og Kittys storesøster. Børnene, økonomien og mandens utroskab præger hendes hverdag. Hendes besøg og samtaler forbinder romanens familier.')]
  why=[('Et spørgsmål om familier','Åbningens påstand om lykkelige og ulykkelige familier lægger op til at blive prøvet mod de liv, der følger. Kærligheden fjerner ikke presset fra penge, børn, vaner eller ulige forventninger. Læg mærke til, hvordan hjemmet ser forskelligt ud for dem, der bor i det.'),('Et samfund i forandring','Romanen stiller personlige beslutninger ved siden af landbrug, provinsvalg, offentlige stillinger og diskussioner om krig. Til sidst diskuteres de frivillige, der støtter Serbien mod Det Osmanniske Rige. Personerne er uenige om medfølelse, nationalfølelse, offentlig mening og retten til at føre krig. Deres argumenter skal læses som forskellige stemmer.'),('Mening i hverdagen','Levins overvejelser vokser ud af erfaringer, som tanken alene ikke kan løse: sygdom, ægteskab, fødsel, arbejde og frygt for dem, han elsker. Hans sidste erkendelse gør ham ikke med ét tålmodig eller fri for tvivl. Læs den almindelige samtale omkring den sammen med selve eftertanken.')]
 d['angleCards']=[dict(title=a,text=b,angleObjective=c)for a,b,c in cards];d['cast']=[dict(name=a,role=b,description=c)for a,b,c in casts];d['whyItMatters']=[dict(title=a,body=b)for a,b in why];d['acclaim']=[]
 d['openingText']=json.loads((p/f'candidate-anna-karenina-modern-{lang}.json').read_text())['chapters'][0]['paragraphs'][0]
 out='candidate-anna-karenina'+('.da' if lang=='da' else '')+'.json';(p/out).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 ledger=[{'field':k,'before':before.get(k),'after':v,'reason':'Source-led guide rewrite: remove factual errors, unsupported superlatives/quotes, inaccurate plot geography and claims that fiction is literal biography; add Dolly and name aid.'}for k,v in d.items() if before.get(k)!=v]
 (p/f'GUIDE-REPAIRS-{lang}.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
(p/'GUIDE-SOURCES.json').write_text(json.dumps({'body':'Russian original full239chapters and candidates, local source-russian-NNN.txt','publication_dates':'https://tolstoy.ru/creativity/fiction/anna-karenina.php','part8_dispute':'https://tolstoy.ru/online/90/83/','later_novel_disproving_never_again':'https://tolstoy.ru/online/90/67/','corrections':['Serialization1875–1877 not four years.','Part8dispute about Russian volunteers in Serbia, not simplistically Russian state war.','Anna finalstationObiralovka not Moscow firstmeeting station.','Anna attends opera withoutVronsky initially; omitted false account.','No claim Tolstoy neverwrote anothernovel; Resurrection1899.','No claim Levin literalautobiography or novelopening mostquoted.','Removed unsourced praise quotations; acclaim empty array pending verified restoration.','Opening matches candidate exact; Dollyaddedcast.'],'native_review':'pending','display_validation':'not performed; no app edits'},ensure_ascii=False,indent=2)+'\n')
